"""도로 / 차량 / 배경 교통류 설정 파일 — 명동 신세계 앞 (한국은행 앞 → 회현사거리, 남쪽 방향).

이 파일의 값을 수정한 뒤 train.py / view_road.py를 다시 실행하면
road_builder.py가 SUMO 도로 파일(.net.xml 등)을 자동으로 다시 만들어준다.

설계 문서: docs/myeongdong_sumo_design.md (좌표·차로 수의 근거와 단순화 내용)

단위 참고:
    - 거리: m (미터),  좌표 원점 = ① 한국은행 앞 교차로, x = 동쪽, y = 북쪽
    - 속도: m/s  (참고: 13.89 m/s = 50 km/h, 서울 도심 안전속도 5030)
"""

# ──────────────────────────────────────────────────────────────
# 1) 도로망
#
#   시청·을지로 → ① J1 한국은행 앞(신호) → 소공로 S1(약 75m, 4차로)
#   → 합류점 MG(숭례문 쪽 우회 도로 1차로가 신호 없이 합류) → S1b(약 35m, 4차로)
#   → 확폭점 M → S2(76m, 7차로: 좌3·직3·우1) → ③ J3 회현사거리(신호) → 진출 3방향
#
#   두 신호 사이(약 187m)에서 세 방향 진입 차량이 세 방향 진출 차로로
#   다시 갈라진다 = "신호 사이 엇갈림(눈치싸움)"이 이 환경의 핵심.
#   `*` 표시 값은 OSM에 차로 태그가 없거나 추정이라 거리뷰 확인 예정.
# ──────────────────────────────────────────────────────────────
# 숭례문 쪽 우회 도로의 갈림점 이후 모양 (ROAD의 W_in과 영상용 배경 교통의 W_in_b가 같이 쓴다).
#   분수대 북쪽을 동쪽으로 오다가 우회전하자마자(MP) 소공로 본선의 맨 오른쪽 차로가 된다 (위성사진, 11/4).
#   끝점은 본선 바깥 가장자리(중심선에서 12.8 m) 선 위라 S1m 0번 차로와 이어진다. 우회전 모서리는 반지름 약 8 m
_BYPASS_TAIL = [(-45.4, -32.4), (-4.7, -33.5), (-0.3, -34.9), (2.7, -38.3)]

ROAD = {
    "speed_limit": 13.89,  # 제한속도 (m/s, 50 km/h). ego 최고속도이자 관측/보상의
                           # 속도 정규화 기준(vmax). 50 km/h로 확정 (11/4). 식(속도/제한속도)은
                           # 그대로이고 제한속도는 팀별로 실제 도로에 맞추는 도로 설정 (설계 문서 4절)
    "num_lanes": 7,        # 가장 넓은 구간(S2)의 차선 수. ego 기본 시작 차선
                           # ("center" → 7//2 = 3번)과 출력용으로만 쓰인다
    "length": 187,         # ①~③ 소공로 구간 길이 (출력용)

    # 노드: id → (x, y, SUMO 노드 타입)
    "nodes": {
        "J1":    (0.0,    0.0,    "traffic_light"),  # ① 한국은행 앞
        "MP":    (14.4,  -33.0,   "priority"),       # 우회 도로가 우회전해 본선 오른쪽에 붙는 점 (①에서 약 36 m)
        "MG":    (29.9,  -68.75,  "priority"),       # 5→4차로로 줄어드는 점 (신세계 앞, ①에서 약 75 m, 위성사진)
                                                     # 오른쪽 두 차로가 S1b 0번으로 합쳐진다. impatience(TRAFFIC)로 교착 방지.
                                                     # zipper(번갈아 합류)는 교착이 생겨서 쓰지 않음 (11/4)
        "M":     (44.0,  -101.0,  "priority"),       # 소공로 확폭점 (4→7차로)
        "J3":    (79.0,  -168.0,  "traffic_light"),  # ③ 회현사거리
        "N_in":  (-149.0, 219.0,  "priority"),       # 소공로 시청 방향
        "NE_in": (80.0,   250.0,  "priority"),       # 남대문로 을지로 방향 (실제 410m → 250m로 자름)
        "W_in":  (-160.0, -78.0,  "priority"),       # 남대문로 숭례문 방향
        "E_out": (300.0, -130.0,  "priority"),       # 퇴계로 명동 방향
        "S_out": (110.0, -300.0,  "priority"),       # 소공로 남산3호터널 방향
        "W_out": (-150.0, -330.0, "priority"),       # 퇴계로 서울역 방향
    },

    # 엣지: id → (from, to, 차선 수[, 모양 좌표 목록]). 모양을 주면 그 점들을 따라 휜 도로가 된다.
    # 진입로는 "소공로로 들어가는 차로"만 모델링한다 (①을 지나치기만 하는 흐름은 제외).
    "edges": {
        "N_in":  ("N_in",  "J1",    3),   # 소공로 직진 (11/4 확인)
        "NE_in": ("NE_in", "J1",    2),   # 남대문로 → 소공로 좌회전 차로 (로드뷰 확인)
        # 숭례문 쪽 우회 도로 1차로 (로드뷰 확인): ①을 거치지 않고 분수대 북쪽·동쪽을 돌아
        # 우회전하자마자 소공로의 맨 오른쪽 차로가 된다 (실선 없음, 바로 왼쪽으로 차로 변경 가능). 신호 없음.
        # 앞 두 점은 위성사진 도로선(분수대 북쪽)을 ①·③ 기준으로 옮긴 추정값
        "W_in":  ("W_in",  "MP",    1, [(-160.0, -78.0)] + _BYPASS_TAIL),
        "S1":    ("J1",    "MP",    4),   # 소공로 ①→우회 도로가 붙는 점, 본선 4차로 (로드뷰 확인)
        "S1m":   ("MP",    "MG",    5),   # 본선 4 + 우회 1 = 5차로, 차로 변경 자유 (위성사진)
        "S1b":   ("MG",    "M",     4),   # 5→4로 줄어든 뒤 확폭점까지 4차로 (로드뷰 확인)
        "S2":    ("M",     "J3",    7),   # 소공로 확폭 구간 (화살표 좌3·직3·우1, OSM·로드뷰 확인)
        "E_out": ("J3",    "E_out", 3),   # 퇴계로 명동 (로드뷰 확인)
        "S_out": ("J3",    "S_out", 3),   # 소공로 남산3호터널 (로드뷰 확인)
        "W_out": ("J3",    "W_out", 4),   # 퇴계로 서울역 (로드뷰 확인)
    },

    # 차로 연결: (from 엣지, from 차로, to 엣지, to 차로).  차로 0 = 맨 오른쪽.
    # 여기 적은 연결만 생성된다 → 차로별 진행 방향(화살표)이 그대로 강제된다.
    "connections": [
        # ① J1: 진입 방향별로 들어가는 소공로 차로 (차로 수는 확인, 어느 차로로 들어가는지는 추정)
        ("N_in", 0, "S1", 0), ("N_in", 1, "S1", 1), ("N_in", 2, "S1", 2),    # 직진 → 오른쪽 3
        ("NE_in", 0, "S1", 2), ("NE_in", 1, "S1", 3),                        # 좌회전 → 왼쪽 2
        # MP: 본선 4차로는 한 칸씩 왼쪽(1~4)으로, 우회 도로는 맨 오른쪽(0)으로
        ("S1", 0, "S1m", 1), ("S1", 1, "S1m", 2), ("S1", 2, "S1m", 3), ("S1", 3, "S1m", 4),
        ("W_in", 0, "S1m", 0),
        # MG: 오른쪽 두 차로(우회 도로였던 0, 본선 1)가 S1b 0번으로 합쳐진다. 버스는 0번 그대로 정류장으로 간다
        ("S1m", 0, "S1b", 0), ("S1m", 1, "S1b", 0),
        ("S1m", 2, "S1b", 1), ("S1m", 3, "S1b", 2), ("S1m", 4, "S1b", 3),
        # M: 4 → 7 확폭 (오른쪽에 우회전 1, 왼쪽에 좌회전 차로가 생긴다).
        # 확폭 구간엔 실선이 없어서 가운데 차로는 이웃 직진 차로로도 이어 준다. 한 칸짜리 연결만 두면
        # 36 m짜리 S1b 안에서 차로를 못 바꾼 차가 끝에 갇혀 크리스마스에 Teleport가 났음(11/4)
        ("S1b", 0, "S2", 0), ("S1b", 0, "S2", 1),                            # 우회전·직진
        ("S1b", 1, "S2", 1), ("S1b", 1, "S2", 2), ("S1b", 1, "S2", 3),       # 직진
        ("S1b", 2, "S2", 2), ("S1b", 2, "S2", 3), ("S1b", 2, "S2", 4),       # 직진·좌회전
        ("S1b", 3, "S2", 5), ("S1b", 3, "S2", 6),                            # 좌회전
        # ③ J3: OSM turn:lanes = left|left|left|through|through|through|right
        ("S2", 0, "W_out", 0),                                               # 우회전 1 (실제로는 ③ 직전에 갈라지는 전용 길)
        ("S2", 1, "S_out", 0), ("S2", 2, "S_out", 1), ("S2", 3, "S_out", 2), # 직진 3
        ("S2", 4, "E_out", 0), ("S2", 5, "E_out", 1), ("S2", 6, "E_out", 2), # 좌회전 3
    ],

    # 신호 (고정 주기).
    #   J1 ① 한국은행앞: 서울시 공식 신호 이력(T-Data data_id=10382, 교차로 ID 2901)에서 잰 값.
    #       2026-11-02(월) 12시, 주기 170 s. 분석: ~/src/myeongdong-signal-data/report.md
    #       단계 = (녹색 받는 진입로 | 튜플 | None, 녹색 초, 황색 초). None은 소공로 쪽 전부 적색
    #       (모델링하지 않은 회현 좌회전, 남대문로 숭례문↔을지로 직진 등의 몫).
    #       진입로 ↔ 공식 신호그룹: N_in = 그룹 80(nw), NE_in 좌회전 = 그룹 50(ne). 방향 접두어 해석은 추정.
    #       숭례문 쪽 우회 도로(W_in)는 공식 신호연결 MAP에 신호그룹이 없고 ①을 거치지 않는다 (MG에서 합류).
    #       크리스마스(저녁 8시) 값은 TRAFFIC["christmas"]["signals_J1"].
    #   J3: 남쪽 방향 녹색 / 적색. 적색 시간 = 모델링하지 않은 퇴계로 교차 흐름의 몫.
    #   offset: J3 신호를 J1보다 몇 초 늦게 시작할지. ①에서 들어온 차량이
    #           ③ 적신호에 막혀 187m 안에 대기열이 쌓이는 정도를 좌우하는 손잡이.
    "signals": {
        "yellow": 4,
        "J1": [
            ("N_in", 49, 5),     # 시청 → 소공로 직진 (0~54 s)
            (None, 44),          # 소공로 쪽 적색: 회현 좌회전 등 (54~98 s)
            ("NE_in", 31, 4),    # 을지로 → 소공로 좌회전 (98~133 s)
            (None, 37),          # 소공로 쪽 적색: 남대문로 직진 등 (133~170 s)
        ],
        # J3 ③ 회현사거리: 공식 데이터 없음(2884, report.md 8~9절), 현장 측정도 못 해서 **추정값**.
        #   주기는 ①과 같은 170 s(연동 운영 가정), 녹색 비율은 이전 가정(46%) 유지,
        #   offset 20 s = ① 시청 직진 녹색 시작 후 187 m를 달려 도착하는 시간.
        "J3": {"green": 80, "red": 86, "offset": 20,        # 주기 = 80+4(황색)+86 = 170초
               "free": ["W_out"]},   # 서울역 방향 우회전은 신세계 앞에서 갈라지는 전용 길이고 신호 없음 (로드뷰 확인)
    },

    # 버스정류장 '신세계백화점': 차로 위 정차 (로드뷰 확인). 위성사진상 확폭점 M 바로 앞이라
    # 합류 후 구간 S1b 맨 오른쪽 차로(길이 27.7 m) 7~27 m에 둔다. 우회 도로로 들어온 406번도 같은 차로.
    # (예전에 S2 우회전 전용 차로에 두었을 때는 직진 버스가 못 빠져 Teleport가 났음)
    "bus_stop": {"id": "shinsegae", "lane": "S1b_0", "start": 7.0, "end": 27.0},
}

# ──────────────────────────────────────────────────────
# 도로변 장식 — 직선 도로용 나무 배치라서 도심 도로망에서는 끈다.
# ──────────────────────────────────────────────────────
SCENERY = {
    "trees": False,
    # 신세계 미디어파사드(신세계스퀘어) 위치 표시 — GUI 장식일 뿐 시뮬레이션에는 영향 없음.
    # 크리스마스 구경 감속은 이 파사드 앞 도로에서 일어난다 (TRAFFIC["christmas"]["look_zones"]).
    "media_facade": {
        # ㄱ자 스크린 (사용자가 위성사진에 표시한 빨간 선): 광장 쪽 북쪽 면 → 모서리 → 소공로를 따라 남쪽.
        # 서쪽 끝 A는 위성사진 변환값, 도로 쪽 면은 SUMO 차로(S1b 맨 오른쪽) 바깥 가장자리에서 3 m 띄움.
        # 두께 3 m 다각형: 바깥선 A→모서리→M 앞(버스정류장 옆에서 끝남), 안쪽선으로 되돌아옴.
        # 버스정류장 아래(확폭 구간)로 한 번 더 꺾이던 부분은 실제와 달라 뺐다 (11/4)
        "shape": [(-26.2, -86.9), (18.5, -82.1), (28.1, -104.1),
                  (25.4, -105.3), (15.8, -83.3), (-26.2, -89.9)],
        "color": "255,0,200",
    },
}

# ──────────────────────────────────────────────────────────────
# 2) ego 차량 (RL 에이전트가 조종하는 빨간 차)
#    accel/decel은 SUMO 물리엔진이 허용하는 "한계치"이다.
# ──────────────────────────────────────────────────────────────
EGO = {
    "accel": 3.0,          # 최대 가속도 (m/s^2) — 도심 승용차 수준
    "decel": 5.4,          # 최대 감속도 (m/s^2)
    "max_speed": 13.89,    # 차량 자체의 최고속도
    "depart_lane": "best",  # 시작 차선. "best"면 SUMO가 경로에 맞는 차로를 고른다
    "depart_speed": 8,     # 시작 속도 (m/s)
    # 기본 경로 r0 (view_road 등 rou.xml용). 학습 env는 매 Episode OD를 무작위로 고른다:
    # 숭례문에서 들어와(맨 오른쪽) 명동으로 좌회전(맨 왼쪽) — 엇갈림이 가장 큰 조합
    "route": ("W_in", "E_out"),
    # OD 뽑기 비중 (TRAFFIC entries × exit_split 9개, 없는 조합은 1).
    # 엇갈림이 큰 조합(오른쪽 진입 → 왼쪽 진출, 그 반대)을 더 자주 뽑는다.
    "od_weights": {("W_in", "E_out"): 2.0, ("NE_in", "W_out"): 2.0},
    # SUMO speedMode 비트: 8 = 교차로 우선권, 16 = 적신호 정지 → 24.
    # 앞차 안전거리(1)·가감속 한계(2,4)는 꺼서 추돌 회피는 RL이 배우게 둔다.
    "speed_mode": 24,
}

# ──────────────────────────────────────────────────────────────
# 3) 배경 교통류 (SUMO가 알아서 운전하는 일반 차량들)
# ──────────────────────────────────────────────────────────────
TRAFFIC = {
    "max_speed": 13.89,       # 배경차 공통 기본 최고속도 (제한속도와 같게)
    "depart_lane": "best",    # 경로에 맞는 차로에서 생성
    "depart_speed": "max",
    # SUMO vType impatience (0~1): 양보해야 하는 쪽(우회 도로 합류 등)이 오래 기다릴수록 작은 틈도 받아들임.
    # 0이면 크리스마스에 본선이 붐빌 때 합류 차가 못 들어가 밀림, 1.0이면 무리한 진입으로 오히려 정체 (11/4, 시드 30개)
    "impatience": 0.5,

    # ── 진입 교통량 (대/시) × 진출 비율 = OD 9개 flow ──
    # 실측 교통량이 없어 정체·Teleport가 없는 선에서 시작값으로 둔다.
    # (연말 시나리오는 이 값을 키워서 만든다)
    "entries": {"W_in": 350, "N_in": 400, "NE_in": 350},
    "exit_split": {"E_out": 0.35, "S_out": 0.40, "W_out": 0.25},

    # ── 크리스마스 시나리오 스위치 ──
    # 신세계 미디어파사드(ㄱ자 스크린)를 보느라 일부 운전자가 파사드 앞 소공로를
    # 천천히 지나간다. SUMO의 "통과 속도 지정 stop"(speed > 0이면
    # 서지 않고 그 속도로 감속해서 지나감)으로 표현한다.
    # 비율·속도는 실측이 없는 가정값 — 실험 설정으로 두고 발표에서 밝힌다.
    "christmas": {
        "enabled": False,        # True = 크리스마스, False = 평시
        "look_share": 0.3,       # 일반 차량 중 구경하며 감속하는 비율. 감속을 차로에 묶이지 않게 바꾼 뒤
                                 # 1시간 × 시드 30개 Teleport 0 (20~50% 모두 0, 11/4). 50%면 다 같이 막힌
                                 # 상황에 가까워져서 "일부가 구경하며 느려짐"이 보이는 30%로 둠
        "look_speed": 3.0,       # 구경 구간 통과 속도 (m/s, 약 11 km/h)
        # 구경 구간: 사용자가 GUI 화면에 표시한 구간 (11/4). 숭례문 쪽 도로의 갈림점 약 6 m 앞(W_in 116.9 m)
        #   → 우회 도로 → 우회전 뒤 5차로(S1m) → 합류 후 4차로(S1b) 끝(확폭점 M). 경로에 있는 엣지에만 적용되어
        #   시청·을지로 쪽에서 온 구경꾼은 S1m부터 감속한다. W_in_b는 영상용 배경 교통을 켰을 때만 있는 엣지.
        #   끝 None = 엣지 전체: 그 엣지에 구경꾼 차량 분류에만 걸리는 속도 제한을 둬서 차로에 묶이지 않는다.
        #   W_in만 일부(빨간 선부터)라 통과 속도 stop을 쓴다 (끝 -0.3 = 차로 끝 0.3 m 앞, 맨 오른쪽 = 우회 도로 차로)
        "look_zones": [("W_in", 116.9, -0.3), ("W_in_b", 0.0, None), ("S1m", 0.0, None), ("S1b", 0.0, None)],
        # ① 신호 저녁 8시 값: 같은 이력의 19시·21시가 같아서 그 값을 쓴다 (20시 기록 없음). 주기 170 s
        "signals_J1": [("N_in", 56, 5), (None, 37), ("NE_in", 32, 4), (None, 36)],
        "traffic_scale": 1.5,    # 일반 차량 교통량 배율 (연말 인파). 1시간 × 시드 30개 Teleport 0, 진입 대기 평균 1대.
                                 # 1.6배부터 을지로 좌회전 진입로에 대기가 쌓임(1시간 뒤 최대 38대, 1.8배 100대) (11/4)
    },

    # ── 영상용 배경 교통 스위치 (기본 꺼짐) ──
    # 남대문로 숭례문↔을지로 직진 차량. ego와는 ①에서 신호로 나뉘어 상호작용이 없어서 학습·데이터에는
    # 넣지 않고, 주행 영상을 찍을 때만 켠다 (view_road.py --background). 꺼져 있으면 도로망·교통이 그대로다.
    # ① 신호는 공식 이력(교차로 2901)의 남대문로 직진 녹색 시각을 그대로 쓴다:
    #   을지로→숭례문 직진(ne) 98~165 s, 숭례문→을지로 직진(sw) 낮 134~165 s / 저녁 135~165 s.
    # 직진 교통량은 실측이 없는 가정값. 소공로 북쪽 방향은 ③ 신호를 몰라서 아직 없다.
    "background": {
        "enabled": False,
        # 숭례문 쪽은 실제처럼 우회 도로와 한 도로로 붙어 오다가 갈림점(W_sp)에서 나뉜다.
        #   켜면 W_in(진입 엣지 이름 그대로)이 숭례문→갈림점 4차로가 되고, 우회 도로는 W_in_b로 이어진다.
        #   여기서 다시 정의한 엣지(W_in)에서 나가는 기본 연결은 빼고 아래 연결을 쓴다 (road_builder).
        #   갈림점 위치는 기존 우회 도로가 꺾이는 점을 쓴 추정값
        "nodes": {
            "W_sp":  (-45.4,  -32.4, "priority"),   # 우회 도로 갈림점 (추정)
            "NE_bg": (73.9,   252.0, "priority"),   # 남대문로 을지로 쪽 (좌회전 차로 서쪽 옆)
        },
        "edges": {
            "W_in":      ("W_in",  "W_sp",  4),     # 숭례문 → 갈림점: 오른쪽 1 = 우회 도로, 왼쪽 3 = 직진
            "W_in_b":    ("W_sp",  "MP",    1, _BYPASS_TAIL),   # 우회 도로 나머지
            "BG_W_in":   ("W_sp",  "J1",    3),     # 갈림점 → ① (직진)
            # ① → 숭례문도 갈림점을 지나게 나눠야 양방향이 한 교차로로 붙는다 (안 나누면 사이가 찢어져 보임)
            "BG_W_out":  ("J1",    "W_sp",  3),     # ① → 갈림점
            "BG_W_out2": ("W_sp",  "W_in",  3),     # 갈림점 → 숭례문
            "BG_NE_in":  ("NE_bg", "J1",    3),     # 을지로 → ① (직진)
            "BG_NE_out": ("J1",    "NE_in", 3),     # ① → 을지로
        },
        "connections": [("W_in", 0, "W_in_b", 0), ("W_in_b", 0, "S1m", 0)]
                       + [("W_in", i + 1, "BG_W_in", i) for i in range(3)]
                       + [("BG_W_in", i, "BG_NE_out", i) for i in range(3)]
                       + [("BG_NE_in", i, "BG_W_out", i) for i in range(3)]
                       + [("BG_W_out", i, "BG_W_out2", i) for i in range(3)],
        "flows": [("W_in", "BG_NE_out", 500), ("BG_NE_in", "BG_W_out2", 500)],   # 대/시, 가정값
        # ① 신호 전체 (주기 170 s): (초, 녹색 진입로, 황색 진입로). 나머지는 적색
        "phases_J1": [            # 평시 낮 12시
            (49, ("N_in",), ()), (5, (), ("N_in",)), (44, (), ()),
            (31, ("NE_in", "BG_NE_in"), ()), (4, ("BG_NE_in",), ("NE_in",)), (1, ("BG_NE_in",), ()),
            (31, ("BG_NE_in", "BG_W_in"), ()), (4, (), ("BG_NE_in", "BG_W_in")), (1, (), ()),
        ],
        "phases_J1_christmas": [  # 저녁 8시
            (56, ("N_in",), ()), (5, (), ("N_in",)), (37, (), ()),
            (32, ("NE_in", "BG_NE_in"), ()), (4, ("BG_NE_in",), ("NE_in",)), (1, ("BG_NE_in",), ()),
            (30, ("BG_NE_in", "BG_W_in"), ()), (4, (), ("BG_NE_in", "BG_W_in")), (1, (), ()),
        ],
    },

    # ── 버스: 신세계백화점 정류장(02144)에 서는 실제 노선 ──
    #   정류장은 차로 위 정차 (로드뷰 확인). 배차 간격·경로는 카카오맵 노선 정보(서울시 제공, 2026-11-03 조회).
    #   낮 12시(평시)와 저녁 8시(크리스마스) 기준이라 심야 N31(23:30~03:50, 35~40분)은 넣지 않는다.
    #   카카오맵은 노선마다 간격을 하나만 보여 줘서 두 시나리오에 같은 값을 쓴다 → 합계 약 19대/시.
    #   도착은 평균 간격의 포아송 과정(실제 버스도 정시가 아니고, 고정 간격이면 매 Episode 같은 시각에 옴)
    "bus": {
        "stop_duration": 20,              # 정차 시간 (초)
        "lines": {                        # 노선: (진입, 진출, 평균 배차 간격 초)
            # 롯데백화점 정류장(02140)은 소공로 위(웨스틴조선 ↔ 롯데백화점 사이) → 시청 쪽 진입로(N_in)로 들어옴
            # 406은 숭례문 정류장 다음 남대문시장앞을 지나 분수대 옆 우회 도로(W_in)로 들어옴
            "143": ("N_in", "S_out", 360),   # 롯데백화점 → 신세계 → 남산3호터널, 6분
            "406": ("W_in", "S_out", 720),   # 숭례문 → 남대문시장 → 신세계 → 남산3호터널, 12분
            "705": ("N_in", "W_out", 840),   # 롯데백화점 → 신세계 → 남대문시장.회현역 → 서울역, 14분
        },
    },

    # ──────────────────────────────────────────────────────
    # 배경차 컨트롤러(차량추종모델) 믹스 + 운전 성향
    #
    # 차량추종모델 4종은 기존 예제와 같다. 도심에서는 배경차도 자기 진출
    # 차로로 가야 하므로 차선변경을 켜고(keep_lane=False), 차선변경 성향을
    # 섞어서 "눈치싸움"을 만든다:
    #   lc_assertive  : 클수록 좁은 틈에도 끼어듦 (기본 1)
    #   lc_cooperative: 클수록 끼어드는 차에 양보 (0~1, 기본 1)
    #   lc_impatience : 클수록 기다릴수록 조급해져 더 공격적으로 변함 (기본 0)
    # ──────────────────────────────────────────────────────
    "controllers": {
        "krauss": {   # 공격형 — 끼어들기 잘하고 양보 안 함
            "probability": 0.35,
            "carFollowModel": "Krauss",
            "accel": 2.6, "decel": 4.5,
            "tau": 1.0, "min_gap": 2.0,
            "sigma": 0.3,
            "speed_dev": 0.10,
            "color": "1,1,0",    # 노랑
            "keep_lane": False,
            "lc_assertive": 2.0, "lc_cooperative": 0.3, "lc_impatience": 0.6,
        },
        "idm": {      # 양보형 — 끼어드는 차에 잘 비켜줌
            "probability": 0.30,
            "carFollowModel": "IDM",
            "accel": 1.8, "decel": 3.5,
            "tau": 1.2, "min_gap": 2.5,
            "speed_dev": 0.10,
            "color": "0,1,1",    # 시안
            "keep_lane": False,
            "lc_assertive": 0.8, "lc_cooperative": 1.0, "lc_impatience": 0.0,
        },
        "eidm": {     # 보통
            "probability": 0.20,
            "carFollowModel": "EIDM",
            "accel": 2.0, "decel": 4.0,
            "tau": 1.1, "min_gap": 2.0,
            "speed_dev": 0.10,
            "color": "1,0.6,0",  # 주황
            "keep_lane": False,
        },
        "acc": {      # 보통 (크루즈)
            "probability": 0.15,
            "carFollowModel": "ACC",
            "accel": 2.0, "decel": 4.0,
            "tau": 1.5, "min_gap": 2.0,
            "speed_dev": 0.05,
            "color": "1,0,1",    # 마젠타
            "keep_lane": False,
        },
    },

    # 프리필은 직선 도로용이라 끈다. 도심에서는 ego 투입 전 warmup으로 채운다.
    "prefill": {"enabled": False},
}
